// Fixture batch 031: external threads and sheet metal recognition. Generated by tools/fixtures/gen-batch-031.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// The hole attribute of a face (external threads describe themselves with one), as far as the thread goes.
function threadInfo(context is Context, face is Query) returns map
{
    const attributes = getHoleAttributes(context, face);
    if (size(attributes) != 1)
        return { "attributes" : size(attributes) };
    var out = {};
    for (var key in ["holeType", "isTappedHole", "tappedDepth", "majorDiameter", "minorDiameter", "threadPitch", "isExternalThread"])
    {
        const value = attributes[0][key];
        out[key] = value is ValueWithUnits ? round(value / millimeter * 1e6) / 1e6 : value;
    }
    return out;
}

function bodyCounts(context is Context) returns map
{
    const all = qEverything(EntityType.BODY);
    return { "solids" : evaluateQueryCount(context, qBodyType(all, BodyType.SOLID)),
             "active" : evaluateQueryCount(context, qActiveSheetMetalFilter(all, ActiveSheetMetal.YES)) };
}

// external-thread: an M10 thread 15 mm down the top of a 10 mm shaft, its face split
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 40 * millimeter });
    externalThread(context, id + "thread1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(5, 0, 40) * millimeter), "branchOfStandard" : { "standard" : "ISO", "size" : "M10", "pitch" : "1.5 mm" } as LookupTablePath, "depthType" : DepthType.Blind, "threadDepth" : 15 * millimeter, "addChamfer" : false, "addUndercut" : false, "splitFace" : true });
    return { "thread" : threadInfo(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(5, 0, 35) * millimeter)) };
}

