// external-thread: an M10 thread up to the step of a shaft
export function c004(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 5 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    const stepSketch = newSketchOnPlane(context, id + "stepSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(stepSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 8 * millimeter });
    skSolve(stepSketch);
    extrude(context, id + "step", { "entities" : qSketchRegion(id + "stepSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    booleanBodies(context, id + "join", { "tools" : qUnion([qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), qBodyType(qCreatedBy(id + "step", EntityType.BODY), BodyType.SOLID)]), "operationType" : BooleanOperationType.UNION });
    externalThread(context, id + "thread1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(5, 0, 40) * millimeter), "branchOfStandard" : { "standard" : "ISO", "size" : "M10", "pitch" : "1.5 mm" } as LookupTablePath, "depthType" : DepthType.UpToNext, "threadDepth" : 15 * millimeter, "addChamfer" : false, "addUndercut" : false, "splitFace" : true });
    return { "thread" : threadInfo(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(5, 0, 35) * millimeter)) };
}

// sheet-metal-recognize: an L bracket 2 mm thick, extruded 30 mm, recognized as sheet metal with 1 mm bends
export function c005(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skPolyline(s1, "l", { "points" : [vector(0, 0) * millimeter, vector(40, 0) * millimeter, vector(40, 25) * millimeter, vector(38, 25) * millimeter, vector(38, 2) * millimeter, vector(0, 2) * millimeter, vector(0, 0) * millimeter] });
    skSolve(s1);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter });
    sheetMetalRecognize(context, id + "recognize1", { "bodies" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "radius" : 1 * millimeter, "changeThickness" : false, "keepInputParts" : false, "kFactor" : 0.45, "minimalClearance" : 0.02 * millimeter });
    return { "counts" : bodyCounts(context) };
}
